def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(obj, default=(0, 0)):
        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            return obj[0], obj[1]
        return default

    def step_toward(a, b):
        ax, ay = a
        bx, by = b
        return [clamp_step(bx - ax), clamp_step(by - ay)]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def safe_int(x, default=0):
        try:
            return int(x)
        except Exception:
            return default

    env = observation.get("environment_name", "") or ""
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    width = safe_int(observation.get("grid_width"), 0)
    height = safe_int(observation.get("grid_height"), 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward((sx, sy), (ox, oy))

        corners = []
        if width > 0 and height > 0:
            corners = [(0, 0), (0, height - 1), (width - 1, 0), (width - 1, height - 1)]
        if corners:
            target = max(corners, key=lambda c: manhattan(c, (ox, oy)))
            return step_toward((sx, sy), target)
        return [0, 0] if (sx, sy) == (ox, oy) else step_toward((sx, sy), (0, 0))

    if env == "territory_control":
        candidates = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("targets") or []
        best = None
        best_score = None
        for item in candidates:
            tx, ty = pos(item, None) if item is not None else (None, None)
            if tx is None:
                continue
            score = manhattan((sx, sy), (tx, ty))
            if best is None or score < best_score:
                best = (tx, ty)
                best_score = score
        if best is not None:
            return step_toward((sx, sy), best)

        # fallback: move toward opponent or center
        if width > 0 and height > 0:
            center = (width // 2, height // 2)
            return step_toward((sx, sy), center)
        return step_toward((sx, sy), (ox, oy))

