    best = None
    best_score = None
    for item in resources:
        tx, ty = pos(item, None) if item is not None else (None, None)
        if tx is None:
            continue
        score = manhattan((sx, sy), (tx, ty))
        if best is None or score < best_score:
            best = (tx, ty)
            best_score = score
    if best is not None:
        return step_toward((sx, sy), best)

    # fallback behavior: if in danger or no resources, prefer a simple evasive/central move
    if width > 0 and height > 0:
        center = (width // 2, height // 2)
        if env == "resource_collection" and (ox, oy) != (sx, sy):
            away = (sx + clamp_step(sx - ox), sy + clamp_step(sy - oy))
            # slight bias toward center when away move is neutral
